:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a3d;
  --text: #f0f0f5;
  --accent: #6c5ce7;
  --accent-hover: #7d6ff0;
  --tile-colors: #e74c3c, #3498db, #2ecc71, #f1c40f;
  --tile-size: 70px;
  --gap: 8px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  max-width: 420px;
  width: 100%;
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 8px;
}

.subtitle {
  font-size: 1rem;
  opacity: 0.8;
  margin-bottom: 16px;
}

.status-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.swap-counter {
  font-size: 1.125rem;
  font-weight: 600;
}

.btn {
  background: var(--accent);
  color: white;
  border: none;
  border-radius: 8px;
  padding: 10px 20px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

.btn:hover {
  background: var(--accent-hover);
}

.btn:focus-visible {
  outline: 3px solid white;
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
  margin-bottom: 16px;
  justify-content: center;
}

.tile {
  width: 100%;
  aspect-ratio: 1;
  border-radius: 8px;
  border: 2px solid transparent;
  cursor: pointer;
  transition: transform 0.1s, border-color 0.2s, box-shadow 0.2s;
  padding: 0;
  background: none;
}

.tile:hover {
  transform: scale(1.05);
}

.tile:focus-visible {
  outline: 3px solid white;
  outline-offset: 2px;
  border-color: transparent;
}

.tile.selected {
  border-color: white;
  box-shadow: 0 0 0 3px var(--accent);
}

.tile:active {
  transform: scale(0.95);
}

.win-message {
  font-size: 1.5rem;
  font-weight: 700;
  color: #2ecc71;
  margin-top: 8px;
}

.instructions {
  font-size: 0.875rem;
  opacity: 0.7;
  margin-top: 16px;
  line-height: 1.4;
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .tile {
    border-radius: 6px;
  }
}

const COLORS = ['#e74c3c', '#3498db', '#2ecc71', '#f1c40f'];
const SIZE = 4;

let board = [];
let selected = null;
let swaps = 0;
let solved = false;

const boardEl = document.getElementById('board');
const swapCountEl = document.getElementById('swapCount');
const winMessageEl = document.getElementById('winMessage');
const shuffleBtn = document.getElementById('shuffleBtn');

function createSolvedBoard() {
  const b = [];
  for (let r = 0; r < SIZE; r++) {
    b.push(Array(SIZE).fill(COLORS[r]));
  }
  return b;
}

function shuffleBoard() {
  board = createSolvedBoard();
  // Apply random swaps to scramble
  for (let i = 0; i < 50; i++) {
    const r1 = Math.floor(Math.random() * SIZE);
    const c1 = Math.floor(Math.random() * SIZE);
    const dirs = [[0,1],[1,0],[0,-1],[-1,0]];
    const [dr, dc] = dirs[Math.floor(Math.random() * 4)];
    const r2 = r1 + dr;
    const c2 = c1 + dc;
    if (r2 >= 0 && r2 < SIZE && c2 >= 0 && c2 < SIZE) {
      [board[r1][c1], board[r2][c2]] = [board[r2][c2], board[r1][c1]];
    }
  }
  // Ensure not solved
  if (isSolved()) {
    // swap two adjacent tiles to break solved state
    [board[0][0], board[0][1]] = [board[0][1], board[0][0]];
  }
}

function isSolved() {
  for (let r = 0; r < SIZE; r++) {
    const first = board[r][0];
    for (let c = 1; c < SIZE; c++) {
      if (board[r][c] !== first) return false;
    }
  }
  return true;
}

function render() {
  boardEl.innerHTML = '';
  for (let r = 0; r < SIZE; r++) {
    for (let c = 0; c < SIZE; c++) {
      const tile = document.createElement('button');
      tile.className = 'tile';
      tile.style.backgroundColor = board[r][c];
      tile.dataset.row = r;
      tile.dataset.col = c;
      tile.setAttribute('aria-label', `Tile row ${r+1} column ${c+1}`);
      if (selected && selected.r === r && selected.c === c) {
        tile.classList.add('selected');
      }
      tile.addEventListener('click', onTileClick);
      boardEl.appendChild(tile);
    }
  }
}

function onTileClick(e) {
  if (solved) return;
  const r = parseInt(e.currentTarget.dataset.row);
  const c = parseInt(e.currentTarget.dataset.col);

  if (!selected) {
    selected = { r, c };
    render();
    return;
  }

  if (selected.r === r && selected.c === c) {
    selected = null;
    render();
    return;
  }

  const dr = Math.abs(selected.r - r);
  const dc = Math.abs(selected.c - c);
  if (dr + dc === 1) {
    // swap
    [board[selected.r][selected.c], board[r][c]] = [board[r][c], board[selected.r][selected.c]];
    swaps++;
    swapCountEl.textContent = swaps;
    selected = null;
    render();
    if (isSolved()) {
      solved = true;
      winMessageEl.hidden = false;
    }
  } else {
    // not adjacent: select new tile
    selected = { r, c };
    render();
  }
}

function startNewGame() {
  shuffleBoard();
  selected = null;
  swaps = 0;
  solved = false;
  swapCountEl.textContent = '0';
  winMessageEl.hidden = true;
  render();
}

shuffleBtn.addEventListener('click', startNewGame);

// Initialize
startNewGame();
